import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link } from "react-router-dom";
import { createMilestone, createProject, listProjects, type ProjectPayload } from "@/api/projects";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Input, Label, Select, Textarea } from "@/components/ui/Input";
import { Alert, EmptyState, PageLoader } from "@/components/ui/Feedback";
import { extractErrorMessage } from "@/api/client"; import { formatCurrency, formatDate } from "@/lib/utils";
const blank={name:"",description:"",role:"",required_skills:"",start_date:"",end_date:"",location:"",work_mode:"HYBRID",working_hours:40,pay_rate:"",currency:"INR"};
const emptyMilestone=()=>({name:"",start_date:"",due_date:"",description:"",priority:"MEDIUM",status:"UPCOMING"});
export function VendorProjects(){const qc=useQueryClient(),[open,setOpen]=useState(false),[form,setForm]=useState(blank),[milestones,setMilestones]=useState([emptyMilestone()]),[error,setError]=useState<string|null>(null);const {data:projects,isLoading}=useQuery({queryKey:["vendor-projects"],queryFn:listProjects});const save=useMutation({mutationFn:createProject,onSuccess:async p=>{for(const m of milestones.filter(m=>m.name))await createMilestone(p.id,{...m,start_date:m.start_date||form.start_date,due_date:m.due_date||form.end_date||form.start_date});qc.invalidateQueries({queryKey:["vendor-projects"]});setForm(blank);setMilestones([emptyMilestone()]);setOpen(false)}});function submit(e:React.FormEvent){e.preventDefault();const pay=Number(form.pay_rate);if(!pay)return setError("Hourly pay rate is required.");save.mutate({...form,pay_rate:pay,end_date:form.end_date||null,description:form.description||null,required_skills:form.required_skills||null,location:form.location||null} as ProjectPayload)}return <div className="space-y-6"><div className="flex justify-between"><div><h1 className="text-2xl font-bold text-ink-900">Projects &amp; Workforce</h1><p className="mt-1 text-sm text-ink-500">Projects, workforce assignments and milestone delivery plans.</p></div><Button onClick={()=>setOpen(!open)}>{open?"Close":"+ Create Project"}</Button></div>{open&&<Card><CardHeader><CardTitle>Create project with milestones</CardTitle></CardHeader><form onSubmit={submit}><CardContent className="space-y-5">{(error||save.isError)&&<Alert variant="error">{error||extractErrorMessage(save.error)}</Alert>}<div className="grid gap-4 sm:grid-cols-2">{([['name','Project name *'],['role','Role *'],['required_skills','Required skills'],['location','Location']] as const).map(([k,l])=><div key={k}><Label>{l}</Label><Input required={k==='name'||k==='role'} value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></div>)}<div><Label>Start date *</Label><Input type="date" required value={form.start_date} onChange={e=>setForm({...form,start_date:e.target.value})}/></div><div><Label>End date</Label><Input type="date" value={form.end_date} onChange={e=>setForm({...form,end_date:e.target.value})}/></div><div><Label>Work mode</Label><Select value={form.work_mode} onChange={e=>setForm({...form,work_mode:e.target.value})}><option>REMOTE</option><option>HYBRID</option><option>ONSITE</option></Select></div><div><Label>Working hours/week</Label><Input type="number" value={form.working_hours} onChange={e=>setForm({...form,working_hours:Number(e.target.value)})}/></div><div><Label>Hourly pay rate *</Label><Input type="number" step=".01" required value={form.pay_rate} onChange={e=>setForm({...form,pay_rate:e.target.value})}/></div></div><div><Label>Description</Label><Textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></div><div className="border-t border-ink-100 pt-4"><div className="mb-3 flex justify-between"><p className="font-semibold text-ink-800">Milestones</p><Button type="button" size="sm" variant="outline" onClick={()=>setMilestones([...milestones,emptyMilestone()])}>+ Add Milestone</Button></div>{milestones.map((m,i)=><div key={i} className="mb-3 rounded-lg bg-ink-50 p-3"><div className="grid gap-3 sm:grid-cols-3"><Input placeholder="Milestone name" value={m.name} onChange={e=>{const x=[...milestones];x[i].name=e.target.value;setMilestones(x)}}/><Input type="date" value={m.start_date} onChange={e=>{const x=[...milestones];x[i].start_date=e.target.value;setMilestones(x)}}/><Input type="date" value={m.due_date} onChange={e=>{const x=[...milestones];x[i].due_date=e.target.value;setMilestones(x)}}/><Select value={m.priority} onChange={e=>{const x=[...milestones];x[i].priority=e.target.value;setMilestones(x)}}><option>LOW</option><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></Select><Select value={m.status} onChange={e=>{const x=[...milestones];x[i].status=e.target.value;setMilestones(x)}}><option>UPCOMING</option><option>IN_PROGRESS</option><option>COMPLETED</option><option>DELAYED</option></Select><Input placeholder="Description" value={m.description} onChange={e=>{const x=[...milestones];x[i].description=e.target.value;setMilestones(x)}}/></div>{milestones.length>1&&<button type="button" className="mt-2 text-xs text-red-600" onClick={()=>setMilestones(milestones.filter((_,n)=>n!==i))}>Remove milestone</button>}</div>)}</div><div className="flex justify-end"><Button isLoading={save.isPending}>Create Project</Button></div></CardContent></form></Card>}<Card>{isLoading?<PageLoader/>:!projects?.length?<EmptyState title="No projects yet"/>:<div className="divide-y divide-ink-100">{projects.map(p=><div className="flex justify-between px-5 py-4" key={p.id}><Link to={`/vendor/projects/${p.id}`}><p className="font-semibold text-ink-900">{p.name}</p><p className="text-sm text-ink-500">{p.role} · {formatDate(p.start_date)} → {formatDate(p.end_date)} · {p.assigned_contractors_count} assigned</p></Link><div className="text-right"><p className="text-sm font-medium text-brand-700">{formatCurrency(p.pay_rate,p.currency)} pay/hr</p><Link to={`/vendor/projects/${p.id}`}><Button size="sm" variant="outline" className="mt-1">View timeline</Button></Link></div></div>)}</div>}</Card></div>}
